     2	
     3	export interface Room {
     4	  readonly id: string;
     5	  readonly label: string;
     6	  readonly turnaroundMinutes: number;
     7	}
     8	
     9	export interface Booking {
    10	  readonly id: string;
    11	  readonly roomId: string;
    12	  readonly production: string;
    13	  readonly durationMinutes: number;
    14	  readonly status: BookingStatus;
    15	}
    16	
    17	export interface DayPlan {
    18	  readonly date: string;
    19	  readonly rooms: readonly Room[];
    20	  readonly bookings: readonly Booking[];
    21	}
    22	
    23	export interface DeskSummary {
    24	  readonly date: string;
    25	  readonly roomCount: number;
    26	  readonly confirmedCount: number;
    27	  readonly rehearsalMinutes: number;
    28	}
    29	
    30	export function confirmedBookings(plan: DayPlan): readonly Booking[] {
    31	  return plan.bookings.filter((booking) => booking.status === "confirmed");
    32	}
    33	
    34	export function deskSummary(plan: DayPlan): DeskSummary {
    35	  const bookings = confirmedBookings(plan);
    36	  return {
    37	    date: plan.date,
    38	    roomCount: plan.rooms.length,
    39	    confirmedCount: bookings.length,
    40	    rehearsalMinutes: bookings.reduce(
    41	      (minutes, booking) => minutes + booking.durationMinutes,
    42	      0,
    43	    ),
    44	  };
    45	}
    46	
    47	export function roomLabel(plan: DayPlan, roomId: string): string | undefined {
    48	  return plan.rooms.find((room) => room.id === roomId)?.label;
    49	}
    50	
    51	export function bookingsForProduction(
    52	  plan: DayPlan,
    53	  production: string,
    54	): readonly Booking[] {
    55	  return plan.bookings.filter((booking) => booking.production === production);
    56	}
