     1	export type BookingStatus = "confirmed" | "tentative" | "cancelled";
     2	
     3	export interface Room {
     4	  readonly id: string;
     5	  readonly label: string;
     6	  readonly turnaroundMinutes: number;
     7	}
     8	
     9	export interface Booking {
    10	  readonly id: string;
    11	  readonly roomId: string;
    12	  readonly production: string;
    13	  readonly durationMinutes: number;
    14	  readonly status: BookingStatus;
    15	}
    16	
    17	export interface DayPlan {
    18	  readonly date: string;
    19	  readonly rooms: readonly Room[];
    20	  readonly bookings: readonly Booking[];
    21	}
    22	
    23	export interface DeskSummary {
    24	  readonly date: string;
    25	  readonly roomCount: number;
    26	  readonly confirmedCount: number;
    27	  readonly rehearsalMinutes: number;
    28	}
    29	
    30	export interface RoomWorkload {
    31	  readonly roomId: string;
    32	  readonly bookingCount: number;
    33	  readonly rehearsalMinutes: number;
    34	  readonly occupiedMinutes: number;
    35	}
    36	
    37	export function roomWorkloads(plan: DayPlan): RoomWorkload[] {
    38	  const totals = new Map<string, { count: number; minutes: number }>();
    39	  for (const booking of plan.bookings) {
    40	    if (booking.status !== "confirmed") continue;
    41	    const total = totals.get(booking.roomId) ?? { count: 0, minutes: 0 };
    42	    total.count += 1;
    43	    total.minutes += booking.durationMinutes;
    44	    totals.set(booking.roomId, total);
    45	  }
    46	
    47	  return plan.rooms.map((room) => {
    48	    const total = totals.get(room.id);
    49	    const bookingCount = total?.count ?? 0;
    50	    const rehearsalMinutes = total?.minutes ?? 0;
    51	    return {
    52	      roomId: room.id,
    53	      bookingCount,
    54	      rehearsalMinutes,
    55	      occupiedMinutes:
    56	        rehearsalMinutes + Math.max(bookingCount - 1, 0) * room.turnaroundMinutes,
    57	    };
    58	  });
    59	}
    60	
    61	export function confirmedBookings(plan: DayPlan): readonly Booking[] {
    62	  return plan.bookings.filter((booking) => booking.status === "confirmed");
    63	}
