    66	  const bookings = confirmedBookings(plan);
    67	  return {
    68	    date: plan.date,
    69	    roomCount: plan.rooms.length,
    70	    confirmedCount: bookings.length,
    71	    rehearsalMinutes: bookings.reduce(
    72	      (minutes, booking) => minutes + booking.durationMinutes,
    73	      0,
    74	    ),
    75	  };
    76	}
    77	
    78	export function roomLabel(plan: DayPlan, roomId: string): string | undefined {
    79	  return plan.rooms.find((room) => room.id === roomId)?.label;
    80	}
