    20	    const cached = this.values.get(documentId);
    21	    if (cached !== undefined) {
    22	      return Promise.resolve(cached);
    23	    }
    24	
    25	    const inFlight = this.pending.get(documentId);
    26	    if (inFlight !== undefined) {
    27	      return inFlight;
    28	    }
