     6	export interface SensorBatch {
     7	  readonly sensorId: string;
     8	  readonly readings: readonly Reading[];
     9	}
    10	
    11	export type BatchResult =
    12	  | { readonly ok: true; readonly batch: SensorBatch }
    13	  | { readonly ok: false; readonly error: "invalid-batch" };
    14	
    15	function isRecord(value: unknown): value is Record<string, unknown> {
    16	  return typeof value === "object" && value !== null && !Array.isArray(value);
    17	}
    18	
    19	function toCelsius(value: number, unit: "C" | "F"): number {
    20	  return unit === "F" ? ((value - 32) * 5) / 9 : value;
    21	}
    22	
    23	export function decodeBatch(input: unknown): BatchResult {
    24	  if (!isRecord(input) || typeof input.sensorId !== "string") {
    25	    return { ok: false, error: "invalid-batch" };
    26	  }
    27	  const sensorId = input.sensorId.trim();
    28	  const unit = input.unit;
    29	  if (
    30	    sensorId.length < 1 || sensorId.length > 32 ||
    31	    (unit !== "C" && unit !== "F") ||
    32	    !Array.isArray(input.readings) ||
    33	    input.readings.length < 1 || input.readings.length > 100
    34	  ) {
    35	    return { ok: false, error: "invalid-batch" };
    36	  }
    37	
    38	  const wireReadings: readonly unknown[] = input.readings;
    39	  const readings: Reading[] = [];
    40	  const minimum = unit === "C" ? -80 : -112;
    41	  const maximum = unit === "C" ? 80 : 176;
    42	  let previousAtMs = -1;
    43	  for (const reading of wireReadings) {
    44	    if (!isRecord(reading)) {
    45	      return { ok: false, error: "invalid-batch" };
    46	    }
    47	    const { atMs, value } = reading;
    48	    if (
    49	      typeof atMs !== "number" || !Number.isSafeInteger(atMs) ||
    50	      atMs < 0 || atMs <= previousAtMs ||
    51	      typeof value !== "number" || !Number.isFinite(value) ||
    52	      value < minimum || value > maximum
    53	    ) {
    54	      return { ok: false, error: "invalid-batch" };
    55	    }
    56	    readings.push({ atMs, celsius: toCelsius(value, unit) });
    57	    previousAtMs = atMs;
    58	  }
    59	
    60	  return {
    61	    ok: true,
    62	    batch: { sensorId, readings },
    63	  };
    64	}
