    66	export interface TemperatureRange {
    67	  readonly minimum: number;
    68	  readonly maximum: number;
    69	}
    70	
    71	export function temperatureRange(batch: SensorBatch): TemperatureRange {
    72	  let minimum = Infinity;
    73	  let maximum = -Infinity;
    74	  for (const reading of batch.readings) {
    75	    minimum = Math.min(minimum, reading.celsius);
    76	    maximum = Math.max(maximum, reading.celsius);
    77	  }
