    29	test('concurrent requests share a load, while different keys load independently', async () => {
    30	 const loads = new Map([['a', deferred()], ['b', deferred()]]);
    31	 const calls = [];
    32	 const cache = new PreviewCache(id => { calls.push(id); return loads.get(id).promise; });
    33	 const first = cache.get('a');
    34	 const second = cache.get('a');
    35	 const other = cache.get('b');
    36	 await Promise.resolve();
    37	 assert.deepEqual(calls, ['a', 'b']);
    38	 const a = preview('a', 1), b = preview('b', 1);
    39	 loads.get('a').resolve(a);
    40	 loads.get('b').resolve(b);
    41	 assert.equal(await first, a);
    42	 assert.equal(await second, a);
    43	 assert.equal(await other, b);
    44	 assert.equal(await cache.get('a'), a);
